pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // 1. No vm.assume needed: any address is admissible for calling DrugDealer()
        // 2. Prank as the fuzzed caller and call DrugDealer()
        vm.prank(caller);
        bool succeeded;
        try c.DrugDealer() { succeeded = true; } catch { succeeded = false; }
        // 3. Assert that DrugDealer() always succeeds (does not revert)
        // In the reference, DrugDealer() succeeds for any caller (and sets ceoAddress).
        // The mutant always reverts, so succeeded will be false for some input (e.g., caller != address(0)).
        assertTrue(succeeded, "DrugDealer() should always succeed");
    }
}

