pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newCEO) public {
        // Ensure the caller is not the current ceoAddress to force a change
        vm.assume(newCEO != address(c.ceoAddress()));
        vm.assume(newCEO != address(0));

        // Impersonate the current CEO to call DrugDealer and change the ceoAddress
        address currentCEO = c.ceoAddress();
        vm.prank(currentCEO);
        c.DrugDealer();

        // Verify that after the call, ceoAddress equals the caller's identity
        assertEq(c.ceoAddress(), currentCEO);
    }
}
